MATCH (v:PlantItem:GlobeCheckValve {unit_id: '4'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'TK-503'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(p:PlantItem {tag: 'P-401'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'V-301'}), (b:PlantItem {tag: 'P-302'}), (v:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(head:ProcessInstrumentationFunction {loop_tag: 'LIAH-5032'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (tank:PlantItem {tag: 'TK-501'})-[:line_to]-(v:Valve)<-[:control]-(a:ActuatingFunction)<-[:send_signal_to*1..]-(c:ProcessControlFunction)
RETURN DISTINCT c.loop_tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-601A'})-[:measured_by]->(instrument:PlantItem)
RETURN instrument.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'TI-4026'})-[:is_located_in]->(u:PlantSection)
RETURN u.unit_id AS unit_id
ORDER BY unit_id;

MATCH (t:PlantItem:Tank {unit_id: '5'})
RETURN t.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'TK-601'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (source:PlantItem {tag: 'P-101'})-[:line_to*1..]->(v:Valve)
WHERE EXISTS {
  (v)-[:line_to*1..]->(equipment:Equipment)
}
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-102'}), (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'TK-101'}), (b:PlantItem {tag: 'P-102'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'V-301'}), (b:PlantItem {tag: 'V-401'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'P-302'}), (b:PlantItem {tag: 'P-701'}), (excluded:PlantItem {tag: 'GTV-5005'})
RETURN EXISTS {
  MATCH (a) ((u:PlantItem)-[:line_to]->(v:PlantItem WHERE v <> excluded))+
  (b)
} AS can_flow_without_GTV-5005

MATCH (a:PlantItem {tag: 'P-302'}), (b:PlantItem {tag: 'P-701'}), (excluded:PlantItem {tag: 'GTV-5005'})
RETURN EXISTS {
  MATCH (a)
  ((u:PlantItem)-[:line_to]->(v:PlantItem) WHERE u <> excluded AND v <> excluded)+
  (b)
} AS can_flow_without_GTV_5005

MATCH (a:PlantItem {tag: 'P-502'}), (b:PlantItem {tag: 'E-701'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'TK-601'}), (b:PlantItem {tag: 'E-701'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;
